/*
 * A208747  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A208748; see the Formula section.
 * https://oeis.org/A208747
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) = value T(r,c) of the triangle generated by * T(n,0)=1,
 *            T(1,0)=1, T(2,1)=2, * T(n,k) = T(n-1,k) + 2*T(n-1,k-1) -
 *            2*T(n-2,k-1) + 4*T(n-2,k-2), * T(n,k)=0 if k<0 or k>=n. * The
 *            sequence is read row‑wise: a(1)=T(1,0), a(2)=T(2,0),
 *            a(3)=T(2,1), …
 * Range:     u8 n <= 20, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>

static seq_t **triangle = NULL;     /* triangle[i] points to row i+1 */
static idx_t  triangle_size = 0;    /* number of rows stored */
static idx_t  triangle_cap   = 0;    /* capacity of triangle array */

/* Ensure the triangle has at least `rows_needed` rows computed.
 * Each new row is computed from the two previous rows. */
static void ensure_triangle(idx_t rows_needed)
{
    if (triangle_size >= rows_needed)
        return;

    /* Grow the rows array if necessary. */
    if (rows_needed > triangle_cap) {
        idx_t new_cap = triangle_cap ? triangle_cap * 2 : 8;
        if (new_cap < rows_needed)
            new_cap = rows_needed;
        triangle = (seq_t **)realloc(triangle, new_cap * sizeof(seq_t *));
        triangle_cap = new_cap;
    }

    for (idx_t r = triangle_size + 1; r <= rows_needed; ++r) {
        idx_t len = r;
        seq_t *row = (seq_t *)malloc(len * sizeof(seq_t));
        if (!row) {
            /* Allocation failure – abort as per ISO C. */
            abort();
        }

        if (r == 1) {
            row[0] = (seq_t)1;
        } else if (r == 2) {
            row[0] = (seq_t)1;
            row[1] = (seq_t)2;
        } else {
            seq_t *prev1 = triangle[r - 2]; /* row r-1 */
            seq_t *prev2 = triangle[r - 3]; /* row r-2 */
            for (idx_t k = 0; k < len; ++k) {
                seq_t val = 0;
                if (k < len - 1)               /* T(r-1,k) */
                    val += prev1[k];
                if (k >= 1 && k - 1 < len - 1)  /* 2*T(r-1,k-1) */
                    val += (seq_t)2 * prev1[k - 1];
                if (k >= 1 && k - 1 < len - 2)  /* -2*T(r-2,k-1) */
                    val -= (seq_t)2 * prev2[k - 1];
                if (k >= 2 && k - 2 < len - 2)  /* +4*T(r-2,k-2) */
                    val += (seq_t)4 * prev2[k - 2];
                row[k] = val;
            }
        }
        triangle[r - 1] = row;
    }
    triangle_size = rows_needed;
}

/* Find the row `r` such that r(r+1)/2 >= n.
 * Use a simple incremental search – r is O(√n). */
static idx_t find_row(idx_t n)
{
    idx_t r = 1;
    while ((r * (r + 1)) / 2 < n)
        ++r;
    return r;
}

seq_t a(idx_t n)
{
    if (n == 0) {
        /* Sequence is 1-indexed; return 0 for out-of-range. */
        return (seq_t)0;
    }
    idx_t r = find_row(n);
    idx_t j = (n - ((r - 1) * r) / 2) - 1;  /* column index (0‑based) */
    ensure_triangle(r);
    return triangle[r - 1][j];
}
